import{_ as t}from"./chunks/panel-workspace.DfVZw37W.js";import{_ as o,a,b as r}from"./chunks/history-panel.6sAeqJNw.js";import{_ as n,o as s,c as d,a2 as i}from"./chunks/framework.Dx-TCpNt.js";const y=JSON.parse('{"title":"Panel Workbench","description":"The panel workbench is where a page becomes structured data. Automatic detection is only the first pass; the workbench exists so you can argue with it —…","frontmatter":{"description":"The panel workbench is where a page becomes structured data. Automatic detection is only the first pass; the workbench exists so you can argue with it —…"},"headers":[],"relativePath":"guide/panels.md","filePath":"guide/panels.md","lastUpdated":1794778569000}'),l={name:"guide/panels.md"};function h(c,e,p,g,u,m){return s(),d("div",null,[...e[0]||(e[0]=[i('<h1 id="panel-workbench" tabindex="-1">Panel Workbench <a class="header-anchor" href="#panel-workbench" aria-label="Permalink to &quot;Panel Workbench&quot;">​</a></h1><p>The panel workbench is where a page becomes structured data. Automatic detection is only the first pass; the workbench exists so you can argue with it — quickly, and without breaking anything permanently.</p><figure class="shot"><img src="'+t+'" alt="Panel workbench with four detected panels, resize handles and the annotation toolbar"><figcaption>Detected panels are drawn as numbered boxes over the base image. The selected box shows eight resize handles. The annotation toolbar sits below the panel tools.</figcaption></figure><h2 id="the-problem-it-solves" tabindex="-1">The problem it solves <a class="header-anchor" href="#the-problem-it-solves" aria-label="Permalink to &quot;The problem it solves&quot;">​</a></h2><p>Every later feature stands on panels: compare reading, panel-scoped notes, PNG panel export, HTML export. If the boxes are wrong, everything downstream inherits the mistake. Automatic detection handles most pages fine, but splash pages, spreads, edge strips and whatever the magazine decided to do that month always need a hand.</p><h2 id="the-toolbar-control-by-control" tabindex="-1">The toolbar, control by control <a class="header-anchor" href="#the-toolbar-control-by-control" aria-label="Permalink to &quot;The toolbar, control by control&quot;">​</a></h2><figure class="shot"><img src="'+o+'" alt="Panel workbench toolbar with base image, detection status, split controls, save mode, grid and templates"><figcaption>The two toolbar rows: detection and saving on top, the rectangle fields, grid generator and panel templates below. The annotation toolbar follows underneath.</figcaption></figure><h3 id="row-1-—-base-image-and-splitting" tabindex="-1">Row 1 — base image and splitting <a class="header-anchor" href="#row-1-—-base-image-and-splitting" aria-label="Permalink to &quot;Row 1 — base image and splitting&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Control</th><th>What it does</th><th>Notes</th></tr></thead><tbody><tr><td><strong>Base image</strong> selector</td><td>Chooses which language&#39;s artwork is shown and used for detection.</td><td>Panel rectangles are shared by all languages on the page, so this only changes the picture you draw on.</td></tr><tr><td>Detector chip</td><td>Shows the algorithm version that produced the current panels, e.g. <code>xycut-1.3</code>, <code>layout:&lt;id&gt;</code>, <code>plugin:&lt;name&gt;</code>.</td><td><code>Legacy data</code> means the page JSON predates version tracking.</td></tr><tr><td>Status text</td><td>Shows whether the panels are <em>Auto</em>, <em>Template</em>, <em>Plugin</em> or <em>Manually edited</em>, plus the save count and the last edit summary.</td><td>This is an edit counter, not an audit log.</td></tr><tr><td><strong>Auto split</strong></td><td>Runs detection on the base image and replaces the current panels.</td><td>Disabled while detection is running or when the page has no image. Re-running detection discards hand edits.</td></tr><tr><td><strong>Add panel</strong></td><td>Adds a default panel near the centre of the page.</td><td>Faster alternative: double-click empty space.</td></tr><tr><td><strong>Merge (n)</strong></td><td>Merges the selected panels into one box with <code>source: &quot;merged&quot;</code>.</td><td>Enabled with two or more selected panels.</td></tr><tr><td><strong>Group (n)</strong></td><td>Creates a group from the selected panels.</td><td>Enabled with at least one selected panel. See <a href="#groups">Groups</a>.</td></tr><tr><td><strong>Delete</strong></td><td>Deletes the selected panels and their panel-scoped notes.</td><td>Same as <code>Delete</code> / <code>Backspace</code>.</td></tr></tbody></table><h3 id="row-1-—-saving" tabindex="-1">Row 1 — saving <a class="header-anchor" href="#row-1-—-saving" aria-label="Permalink to &quot;Row 1 — saving&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Control</th><th>What it does</th></tr></thead><tbody><tr><td><strong>Auto</strong></td><td>Saves automatically about 0.7 s after a change.</td></tr><tr><td><strong>Confirm</strong></td><td>Keeps edits dirty until you click <strong>✓</strong> or press <code>Enter</code>. <strong>×</strong> or <code>Esc</code> discards and restores the last save.</td></tr><tr><td><code>↶</code> / <code>↷</code></td><td>Undo / redo (<code>Ctrl+Z</code>, <code>Ctrl+Shift+Z</code>, <code>Ctrl+Y</code>).</td></tr><tr><td><strong>✓</strong></td><td>Saves the dirty page (Confirm mode only).</td></tr><tr><td><strong>×</strong></td><td>Discards unsaved edits (Confirm mode only).</td></tr><tr><td><strong>Unsaved</strong> flag</td><td>Appears in Confirm mode while the page has unsaved changes.</td></tr><tr><td><strong>Numbers</strong></td><td>Shows or hides the panel index badges.</td></tr></tbody></table><p>The save mode is remembered in the browser. The top bar always shows the current state: <em>Saved</em>, <em>Saving…</em>, <em>Pending save</em> or <em>Unsaved changes</em>.</p><h3 id="row-1-—-zoom" tabindex="-1">Row 1 — zoom <a class="header-anchor" href="#row-1-—-zoom" aria-label="Permalink to &quot;Row 1 — zoom&quot;">​</a></h3><p>The <code>−</code> / percentage / <code>＋</code> control changes the stage zoom from 50% to 300% in 15% steps. Zoom is a display setting only; panel coordinates are normalized to <code>0..1</code> and do not change.</p><h3 id="row-2-—-numeric-rectangle" tabindex="-1">Row 2 — numeric rectangle <a class="header-anchor" href="#row-2-—-numeric-rectangle" aria-label="Permalink to &quot;Row 2 — numeric rectangle&quot;">​</a></h3><p>With exactly one panel selected, the second row shows <strong>Panel rect</strong> with four percentage inputs:</p><table tabindex="0"><thead><tr><th>Field</th><th>Meaning</th></tr></thead><tbody><tr><td><code>X</code></td><td>Left edge, percent of page width.</td></tr><tr><td><code>Y</code></td><td>Top edge, percent of page height.</td></tr><tr><td><code>W</code></td><td>Width, percent of page width.</td></tr><tr><td><code>H</code></td><td>Height, percent of page height.</td></tr></tbody></table><p>Typing a value updates the panel immediately. Values outside the page are clamped when saved.</p><h3 id="row-2-—-grid-generator" tabindex="-1">Row 2 — grid generator <a class="header-anchor" href="#row-2-—-grid-generator" aria-label="Permalink to &quot;Row 2 — grid generator&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Field</th><th>Range</th><th>Meaning</th></tr></thead><tbody><tr><td><strong>Rows</strong></td><td>1–8</td><td>Number of rows.</td></tr><tr><td><strong>Columns</strong></td><td>1–6</td><td>Number of columns.</td></tr><tr><td><strong>Gap</strong></td><td>0–8 %</td><td>Gutter between cells, in percent of the page.</td></tr><tr><td><strong>Generate grid</strong></td><td>—</td><td>Replaces the current panels with an evenly divided grid.</td></tr></tbody></table><p>Use the grid for a chapter with a fixed magazine layout; use <strong>Panel templates</strong> when the layout repeats exactly.</p><h3 id="row-2-—-templates-and-json" tabindex="-1">Row 2 — templates and JSON <a class="header-anchor" href="#row-2-—-templates-and-json" aria-label="Permalink to &quot;Row 2 — templates and JSON&quot;">​</a></h3><p><strong>Panel templates</strong> captures the rectangles of the current page:</p><ol><li>Open <strong>Panel templates</strong>, type a name, click <strong>Save this page as a template</strong>.</li><li>Select the template, then <strong>Apply to this page</strong> or <strong>Apply to chapter</strong>.</li><li>Applying to a chapter asks for confirmation because existing panels are overwritten.</li></ol><p>When the new page has the same number of panels as the template, panel-scoped notes are remapped by reading order. When the count differs, panel notes are dropped rather than silently attached to the wrong panel; page notes are always kept. Templates live in <code>data/templates/panel.json</code>.</p><p><strong>Copy JSON path</strong> copies <code>data/pages/&lt;volume&gt;/&lt;chapter&gt;/&lt;index&gt;.json</code>. Editing that file by hand is supported; the server normalizes rectangles, repairs missing ids and drops dangling references on read.</p><h2 id="mouse-and-keyboard-on-the-canvas" tabindex="-1">Mouse and keyboard on the canvas <a class="header-anchor" href="#mouse-and-keyboard-on-the-canvas" aria-label="Permalink to &quot;Mouse and keyboard on the canvas&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Action</th><th>Gesture</th></tr></thead><tbody><tr><td>Move a panel</td><td>Drag the box body.</td></tr><tr><td>Resize</td><td>Drag one of the eight handles.</td></tr><tr><td>Add a panel quickly</td><td>Double-click empty space.</td></tr><tr><td>Draw a panel precisely</td><td>Drag on empty space.</td></tr><tr><td>Constrain to a square</td><td>Hold <code>Shift</code> while drawing.</td></tr><tr><td>Disable snapping</td><td>Hold <code>Alt</code> while drawing or dragging.</td></tr><tr><td>Cancel the current box</td><td><code>Esc</code>.</td></tr><tr><td>Multi-select</td><td><code>Ctrl</code>-click or <code>Shift</code>-click boxes.</td></tr><tr><td>Nudge</td><td>Arrow keys move the selection by 0.2%; <code>Shift</code> + arrow moves by 1%.</td></tr><tr><td>Delete</td><td><code>Delete</code> or <code>Backspace</code>.</td></tr><tr><td>Save / discard (Confirm mode)</td><td><code>Enter</code> / <code>Esc</code>.</td></tr></tbody></table><p>All coordinates are normalized to the page, so a panel stays in the same place at any zoom level or export resolution.</p><h2 id="numbering-and-reading-direction" tabindex="-1">Numbering and reading direction <a class="header-anchor" href="#numbering-and-reading-direction" aria-label="Permalink to &quot;Numbering and reading direction&quot;">​</a></h2><ul><li><strong>Numbers</strong> toggles the index badges.</li><li>Reading direction is stored per page and is one of seven values: <code>rtl</code>, <code>ltr</code>, <code>ttb</code>, <code>horizontal-rl</code>, <code>horizontal-lr</code>, <code>vertical-rl</code> and <code>vertical-lr</code>. The first three are legacy names for the horizontal and vertical forms. Change it in the top bar.</li><li>A panel may carry an explicit <code>number</code> that overrides automatic reading order; otherwise numbering is derived from the rectangle and the direction.</li><li>The same order drives the compare reader, the notes overview and HTML export.</li></ul><div class="tip custom-block"><p class="custom-block-title">Reading order first</p><p>If the numbers look wrong before you have touched anything, fix the reading-direction selector first. Hand-numbering panels in the JSON is possible, but changing the direction repairs the whole chapter at once.</p></div><h2 id="annotation-tools" tabindex="-1">Annotation tools <a class="header-anchor" href="#annotation-tools" aria-label="Permalink to &quot;Annotation tools&quot;">​</a></h2><p>The annotation layer draws on top of the artwork and lives separately from panels — think of it as your red pen, not part of the page geometry.</p><figure class="shot"><img src="'+a+'" alt="Annotation toolbar with visibility, select, shapes, highlighter, freehand, text, badge, mosaic, colour swatches and clear-all"><figcaption>The annotation toolbar. The hint on the right names the current scope — here, new marks cover the whole page. The same toolbar appears in the compare reader.</figcaption></figure><table tabindex="0"><thead><tr><th>Control</th><th>What it does</th></tr></thead><tbody><tr><td><strong>Annotations: Shown / Hidden</strong></td><td>Global visibility. Hiding keeps the data and hides it in exports.</td></tr><tr><td><strong>Select and move</strong></td><td>Select an existing mark; drag to move it.</td></tr><tr><td><strong>Arrow</strong></td><td>Drag from tail to head.</td></tr><tr><td><strong>Rectangle</strong> / <strong>Ellipse</strong></td><td>Drag a box or oval.</td></tr><tr><td><strong>Highlighter</strong></td><td>Semi-transparent freehand stroke.</td></tr><tr><td><strong>Freehand</strong></td><td>Opaque pen stroke; keeps the full polyline.</td></tr><tr><td><strong>Text</strong></td><td>Click, then type the label.</td></tr><tr><td><strong>Number badge</strong></td><td>Click, then type a number.</td></tr><tr><td><strong>Mosaic</strong></td><td>Drag a rectangle; the area is pixelated.</td></tr><tr><td><strong>Colour swatches</strong></td><td>Sets the colour for new marks; clicking a swatch while a mark is selected recolours it.</td></tr><tr><td><strong>Delete</strong></td><td>Deletes the selected mark.</td></tr><tr><td><strong>Clear all</strong></td><td>Deletes every mark on the page after confirmation.</td></tr></tbody></table><p>Scope follows the selection: with one panel selected, the hint reads <em>New marks go inside panel N</em>; with nothing selected, <em>New marks cover the whole page</em>. <code>Esc</code> leaves the current tool or deselects a mark.</p><p>Exported HTML and PNG include annotations only when the layer is shown. The HTML export also has a <strong>Draw panel borders on the original image</strong> option, which is separate from annotations.</p><h2 id="groups" tabindex="-1">Groups <a class="header-anchor" href="#groups" aria-label="Permalink to &quot;Groups&quot;">​</a></h2><p>A group is a named set of panels that should be read as one unit: a double-page spread split into two boxes, a recurring establishing shot, or a sequence you want to talk about as a block. Groups are layout metadata only — they never merge artwork, move notes or change annotations.</p><h3 id="create-a-group" tabindex="-1">Create a group <a class="header-anchor" href="#create-a-group" aria-label="Permalink to &quot;Create a group&quot;">​</a></h3><ol><li>Select one or more panels: <code>Ctrl</code>-click, <code>Shift</code>-click, or drag a marquee on empty space.</li><li>Click <strong>Group (n)</strong> in the first toolbar row.</li><li>The new group appears in the <strong>Groups (n)</strong> panel. Give it a name and a colour.</li></ol><p>Creating a group removes its panels from any earlier group, so groups never overlap.</p><h3 id="edit-a-group" tabindex="-1">Edit a group <a class="header-anchor" href="#edit-a-group" aria-label="Permalink to &quot;Edit a group&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Control</th><th>What it does</th></tr></thead><tbody><tr><td>Colour swatch</td><td>Colours the group&#39;s panel outlines and chips.</td></tr><tr><td>Name field</td><td>Free text; defaults to <em>Group n</em>.</td></tr><tr><td>Numbered chips</td><td>The panels in the group. Drag a chip to change the order inside the group.</td></tr><tr><td><code>×</code> on a chip</td><td>Removes that panel from the group; the panel itself stays on the page.</td></tr><tr><td><strong>Merge up</strong></td><td>Appends this group&#39;s panels to the group above it. Disabled for the first group.</td></tr><tr><td><strong>Split</strong></td><td>Splits a multi-panel group into one group per panel.</td></tr><tr><td><strong>Delete</strong></td><td>Deletes the group only; its panels, notes and annotations remain.</td></tr></tbody></table><p><strong>Sort by group</strong> in the groups header renumbers the page so that each group follows its first panel in reading order. This changes panel numbering, so use it deliberately; export and compare reading follow the same order.</p><p>Groups are stored in the page JSON as <code>groups: [{ id, name, panelIds, number, color }]</code> and travel with page exchange files, project packages and backups.</p><h2 id="page-history" tabindex="-1">Page history <a class="header-anchor" href="#page-history" aria-label="Permalink to &quot;Page history&quot;">​</a></h2><p>Every save also appends a version to <code>data/history/&lt;volume&gt;/&lt;chapter&gt;/&lt;page&gt;.json</code>. Unlike the in-session undo stack, history survives reloads, restarts and project packaging — your safety net for the day a template eats the panels.</p><ol><li>Open a page.</li><li>Click <strong>≡ History</strong> in the top bar.</li><li>Pick a version to inspect it, then <strong>Restore this version</strong> if it is the one you want.</li></ol><figure class="shot"><img src="'+r+'" alt="Page version history dialog with version entries, source labels, panel and annotation counts and restore buttons"><figcaption>Page version history. Each row records why the version was created and the structural change; the current version is marked and cannot be restored over itself.</figcaption></figure><table tabindex="0"><thead><tr><th>Control</th><th>What it does</th></tr></thead><tbody><tr><td>Version row</td><td>Timestamp, source label and the structural diff against the previous version.</td></tr><tr><td>Source labels</td><td><em>auto save</em>, <em>manual save</em>, <em>batch</em>, <em>template</em>, <em>alignment</em>, <em>annotation</em>, <em>import</em>, <em>restore</em>, <em>auto-detect</em>.</td></tr><tr><td>Counts</td><td>Panels, annotations and notes in that version.</td></tr><tr><td><strong>Show panel preview</strong></td><td>Compares the panel rectangles of this version with the previous one.</td></tr><tr><td><strong>Keep latest n versions per page</strong></td><td>History cap, default 50. Older versions are pruned on the next save.</td></tr><tr><td><strong>Restore this version</strong></td><td>Saves the current state as a new version first, then restores the chosen one.</td></tr><tr><td><strong>Undo restore</strong></td><td>Puts back the state from before the last restore.</td></tr></tbody></table><p>Restoring is not the same as undo: it writes a new version, so the state you restored <em>from</em> is still in the list. History files are included in backups and project packages; they are not removed by clearing the thumbnail cache.</p><h2 id="a-safe-correction-workflow" tabindex="-1">A safe correction workflow <a class="header-anchor" href="#a-safe-correction-workflow" aria-label="Permalink to &quot;A safe correction workflow&quot;">​</a></h2><p>A rhythm that keeps you out of trouble:</p><ol><li>Open the page and let automatic detection run.</li><li>Fix obvious boxes: move, resize, add, delete.</li><li>Merge splash-page panels that span a spread.</li><li>Save (or press <code>✓</code> in Confirm mode).</li><li>Switch to <strong>Compare</strong> (<code>C</code>) and check that the same panel really contains the same artwork.</li></ol><p>Avoid re-running <strong>Auto split</strong> after hand edits unless you are willing to lose them.</p><h2 id="common-pitfalls" tabindex="-1">Common pitfalls <a class="header-anchor" href="#common-pitfalls" aria-label="Permalink to &quot;Common pitfalls&quot;">​</a></h2><ul><li><strong>Auto split replaced my boxes.</strong> Detection overwrites. Use a panel template or edit by hand after the first successful split.</li><li><strong>A page has no image.</strong> Detection is disabled and the stage shows an empty state. Add the missing language folder or map it in volume settings.</li><li><strong>WebP pages do not detect.</strong> WebP is displayed but not decoded for detection; convert to JPEG or PNG.</li><li><strong>Panel notes disappeared after applying a template.</strong> The template had a different panel count, so panel notes were dropped; page notes were kept. Restore from a backup if needed.</li><li><strong>“Unsaved changes” will not go away.</strong> You are in Confirm mode. Press <code>✓</code> or <code>Enter</code>; <code>×</code> discards.</li><li><strong>Marks are invisible.</strong> The annotation layer is hidden, or a panel filter is active. Check <strong>Annotations: Shown</strong>.</li><li><strong>Grouping changed the numbering.</strong> <strong>Sort by group</strong> rewrites reading order. Undo it, or create the groups before writing panel notes.</li><li><strong>A restored version lost newer notes.</strong> Restoring replaces the whole page. The state you restored from is kept as a version, so use <strong>Undo restore</strong> or restore that version again.</li></ul><h2 id="missing-screenshots" tabindex="-1">Missing screenshots <a class="header-anchor" href="#missing-screenshots" aria-label="Permalink to &quot;Missing screenshots&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Figure</th><th>Needed for</th></tr></thead><tbody><tr><td>groups panel close-up</td><td>Colour, name, chips and group actions</td></tr><tr><td>panel template panel</td><td>Template save / apply controls</td></tr></tbody></table><h2 id="related" tabindex="-1">Related <a class="header-anchor" href="#related" aria-label="Permalink to &quot;Related&quot;">​</a></h2><ul><li><a href="/KomaYomi-docs/guide/compare">Compare Reader</a> — what panels are for.</li><li><a href="/KomaYomi-docs/guide/project-files">Project Files &amp; Formats</a> — how history and groups are packaged.</li><li><a href="/KomaYomi-docs/data-format">Data Formats</a> — the page JSON contract.</li><li><a href="/KomaYomi-docs/guide/shortcuts">Keyboard Shortcuts</a> — one table for every key.</li></ul>',63)])])}const v=n(l,[["render",h]]);export{y as __pageData,v as default};
